let EN_ALLOWED_VI_WORDS=null;
function enAllowedViWords(){if(EN_ALLOWED_VI_WORDS)return EN_ALLOWED_VI_WORDS;const set=new Set(),add=v=>{if(typeof v!=='string')return;for(const w of v.split(/[^\p{L}]+/u))if(w&&VI_LETTER.test(w))set.add(w.toLowerCase())};for(const v of Object.values(EN_UI))add(v);for(const v of Object.values(INGREDIENT_EN))add(v);for(const o of [VI_PROTEIN_EN,VI_STYLE_EN,typeof VI_VEG_EN!=='undefined'?VI_VEG_EN:{},typeof VI_NOODLE_EN!=='undefined'?VI_NOODLE_EN:{}])for(const v of Object.values(o))add(v);return EN_ALLOWED_VI_WORDS=set}
function englishLeftover(out){const allowed=enAllowedViWords();return out.split(/[^\p{L}]+/u).some(w=>w&&VI_LETTER.test(w)&&!allowed.has(w.toLowerCase()))}
// v1.7.6 (owner report: “Chi tiêu” stayed Vietnamese in English): a family member called “Chi” protected that word, so the
// interface phrase “Chi tiêu” could not be translated. A known interface phrase that contains a family name is translated
// first; the name itself stays protected everywhere else.
function englishUI(text,protectedValues){if(!text)return text;const keep=[];let src=text;
 if(protectedValues){const names=[...protectedValues].filter(v=>v&&v.length>=2);for(const key of EN_TOKENS)if(key.length>4&&src.includes(key)&&names.some(v=>new RegExp('(?<![\\p{L}\\p{N}])'+v.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?![\\p{L}\\p{N}])','u').test(key)))src=src.split(key).join(EN_UI[key])}if(protectedValues)for(const v of protectedValues){if(!v||v.length<2||!src.includes(v))continue;const re=new RegExp('(?<![\\p{L}\\p{N}])'+v.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?![\\p{L}\\p{N}])','gu');if(!re.test(src))continue;src=src.replace(re,'\uE000'+keep.length+'\uE001');keep.push(v)}
 const done=englishUICore(src);if(done!==src&&englishLeftover(done.replace(/\uE000\d+\uE001/g,' ')))return text;return done.replace(/\uE000(\d+)\uE001/g,(_,i)=>keep[+i]);}
function englishUICore(text){const lead=text.match(/^\s*/)[0],tail=text.match(/\s*$/)[0],s=text.trim();if(!s)return text;const recipeDirect=translateRecipeViToEn(s);if(recipeDirect)return lead+recipeDirect+tail;for(const[re,to]of EN_SENTENCE_RULES)if(re.test(s)){const out=s.replace(re,to);if(out!==s)return lead+out+tail}
 let out=s;const tokens=EN_TOKENS;
 // Translate known interface phrases inside icon-prefixed labels, not arbitrary prose.
 for(const key of tokens)if(key.length>4&&out.includes(key))out=out.split(key).join(EN_UI[key]);
 out=out.replace(/Thứ ([2-7])/g,(_,n)=>['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][n-2]).replace(/Chủ Nhật/g,'Sunday').replace(/THỨ ([2-7])/g,(_,n)=>['MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY'][n-2]);
 out=out.replace(/(\d+) món cho bữa cơm nhà/g,'$1 dishes for the family').replace(/(\d+) thành viên/g,'$1 members').replace(/(\d+) bữa sử dụng/g,'Used in $1 meals').replace(/(\d+) việc cần làm/g,'$1 tasks remaining').replace(/(\d+) món & biến thể/g,'$1 dishes & variants').replace(/(\d+) món/g,'$1 dishes').replace(/(\d+) phút/g,'$1 min').replace(/suất chuẩn/g,'standard portions').replace(/nguyên liệu món/g,'dish ingredient cost').replace(/đã mua/g,'bought').replace(/Đã mua/g,'Bought').replace(/hoàn thành/g,'complete').replace(/Đã trừ tồn còn hạn dùng/g,'Unexpired pantry stock deducted').replace(/Đã có/g,'In pantry').replace(/Ngày đang chọn/g,'Selected day').replace(/ngày từ/g,'days from').replace(/Chọn lượng mua/g,'Choose quantity').replace(/^Bỏ (.+) khỏi giỏ$/,'Remove $1 from the list').replace(/Cần ([\d.,]+ ?[^\s·]*) · tủ có ([\d.,]+ ?[^\s·]*) → mua ([\d.,]+ ?[^\s·]*)/g,'Need $1 · pantry has $2 → buy $3').replace(/Báo cơm/g,'Attendance:').replace(/lần ghi nhận/g,'recorded purchases').replace(/(\d+(?:[.,]\d+)?) quả/g,'$1 each').replace(/(\d+(?:[.,]\d+)?) bó/g,'$1 bunches').replace(/(\d+(?:[.,]\d+)?) cái/g,'$1 pieces').replace(/(\d+(?:[.,]\d+)?) gói/g,'$1 packs');return lead+out+tail;
}
// v1.7.14 (owner, 8 Nov 2026: “nhiều món trong pantry dù đã chọn tiếng anh mà không dịch”): an ingredient the family added by name is
// shown in English when its meaning is known for sure (the app's own word list, plus a few qualifiers such as “khô” → dried). A name
// the app does not know stays as written, and the family's own text is never changed in the data.
const FAMILY_EN_EXTRA:Record<string,string>={'bột chiên giòn':'Crispy batter mix','bột chiên xù':'Panko breadcrumbs','bột năng':'Tapioca starch','bột bắp':'Cornflour','bột mì':'Plain flour','hạt nêm':'Stock powder','lạp xưởng':'Chinese sausage','chả lụa':'Vietnamese pork roll','bí đao':'Winter melon','cải thìa':'Bok choy','rau muống':'Water spinach','ngò':'Coriander','hành lá':'Spring onions','hành tím':'Shallots'};
const FAMILY_EN_QUAL:[RegExp,string,string][]=[[/\s*\(còn đuôi\)$/,'',' (tail on)'],[/\s*\(bóc vỏ\)$/,'',' (peeled)'],[/\s+khô$/,'Dried ',''],[/\s+tươi$/,'Fresh ',''],[/\s+đông lạnh$/,'Frozen ','']];
const familyEnMemo=new Map<string,string|null>();
function familyIngredientEnglish(name:string):string|null{const key=String(name||'');if(familyEnMemo.has(key))return familyEnMemo.get(key)!;const v=familyIngredientEnglishRaw(key);if(familyEnMemo.size<2000)familyEnMemo.set(key,v);return v}
function familyIngredientEnglishRaw(name:string):string|null{let n=String(name||'').normalize('NFC').toLowerCase().trim().replace(/\s+/g,' ');if(!n)return null;let pre='',post='';
 for(let k=0;k<3;k++){let hit=false;for(const[re,a,b]of FAMILY_EN_QUAL)if(re.test(n)){n=n.replace(re,'').trim();pre=a+pre;post=post+b;hit=true}if(!hit)break}
 const look=(x:string):string|null=>{if(FAMILY_EN_EXTRA[x])return FAMILY_EN_EXTRA[x];if(typeof VOICE_LEXICON!=='undefined')for(const[id,vi,en,...alt]of VOICE_LEXICON as any[])if(id&&(String(vi).toLowerCase()===x||alt.some((a:any)=>String(a).toLowerCase()===x)))return en;
  for(const[id,row]of Object.entries(INGREDIENTS))if(!id.startsWith('family-ing-')&&String((row as any)[0]).toLowerCase()===x&&(INGREDIENT_EN as any)[id])return (INGREDIENT_EN as any)[id];return null};
 let en=look(n);if(!en&&n.startsWith('rau '))en=look(n.slice(4));if(!en)return null;
 if(pre)en=pre+en.charAt(0).toLowerCase()+en.slice(1);return en+post}
function familyEnglishNames(){const out=new Map<string,string>();for(const[id,x]of Object.entries(state?.ingredientCatalog||{})){const name=String((x as any)?.name||'').trim();const en=name&&familyIngredientEnglish(name);if(en){out.set(name,en);(INGREDIENT_EN as any)[id]=en}else delete (INGREDIENT_EN as any)[id]}return out}
function applyLanguage(root=document.body){
 document.documentElement.lang=appLanguage;
 const famEn=familyEnglishNames();
 const protectedValues=new Set([...state.recipes.filter(r=>r.custom).map(r=>r.name),...state.members.map(m=>m.name),...(state.stores||[]).flatMap(s=>[s.name,s.address]),...Object.values(state.ingredientCatalog||{}).map(x=>x?.name),...(state.products||[]).flatMap(p=>[p.name,p.size,p.branch]),...(state.errands||[]).flatMap(r=>[r.item,r.note,r.from]),...Object.values(state.weeks||{}).flatMap(w=>Object.values(w.days).flatMap(d=>['lunch','dinner'].map(t=>d[t]?.note)))].filter(Boolean));
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
 while(node=walker.nextNode()){const p=node.parentElement;if(!p||p.closest('script,style,textarea,input,[data-user-content]'))continue;const old=englishTextNodes.get(node),source=old&&node.nodeValue===old.translated?old.source:node.nodeValue;if(protectedValues.has(source.trim())){const fe=appLanguage==='en'?famEn.get(source.trim()):null;const want=fe?source.replace(source.trim(),fe):source;if(node.nodeValue!==want)node.nodeValue=want;englishTextNodes.set(node,{source,translated:want});continue}const translated=appLanguage==='en'?englishUI(source,protectedValues):source;if(node.nodeValue!==translated)node.nodeValue=translated;englishTextNodes.set(node,{source,translated})}
 for(const el of root.querySelectorAll('[aria-label],[placeholder],[title]')){let originals=englishAttributes.get(el)||{};for(const attr of ['aria-label','placeholder','title']){if(!el.hasAttribute(attr))continue;const current=el.getAttribute(attr),old=originals[attr],source=old&&old.translated===current?old.source:current,translated=appLanguage==='en'?englishUI(source,protectedValues):source;el.setAttribute(attr,translated);originals[attr]={source,translated}}englishAttributes.set(el,originals)}
}
function updateLanguageControl(){const button=$('#app-language');if(!button)return;const next=appLanguage==='vi'?'en':'vi';button.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18M12 3c-5 5-5 13 0 18"/></svg><b>'+appLanguage.toUpperCase()+'</b>';button.setAttribute('aria-label',appLanguage==='vi'?'Đổi sang tiếng Anh':'Switch to Vietnamese');button.title=appLanguage==='vi'?'Chạm để đổi sang English':'Tap to switch to Tiếng Việt';button.dataset.nextLanguage=next}
function installLanguageControl(){if($('#app-language'))return;const wrap=document.createElement('div');wrap.className='language-control';wrap.innerHTML='<button id="app-language" class="language-toggle" type="button"></button>';$('.top-actions')?.prepend(wrap);updateLanguageControl()}
function changeAppLanguage(next){appLanguage=next==='en'?'en':'vi';try{familyStorage.setItem('bep-language',appLanguage);familyStorage.removeItem('bep-language-auto')/* an explicit choice */}catch(e){}closeModal();render();updateLanguageControl();applyLanguage()}

installLanguageControl();
const languageModal=modal;modal=function(...args){languageModal(...args);applyLanguage($('#modal-root'))};
const languageToast=toast;toast=function(message,error){languageToast(appLanguage==='en'?englishUI(message):message,error)};
const originalFilteredRecipes=filteredRecipes;filteredRecipes=function(){if(appLanguage!=='en'||!recipeSearch)return originalFilteredRecipes();return state.recipes.filter(r=>(recipeFilter==='all'||recipeFilter==='favorite'&&r.favorite||recipeFilter==='western'&&(typeof isWesternRecipe==='function'&&isWesternRecipe(r))||recipeFilter==='healthy'&&(typeof isHealthyRecipe==='function'&&isHealthyRecipe(r))||r.category===recipeFilter)&&(!recipeTime||r.time<=recipeTime)&&(normalizeText(r.name).includes(normalizeText(recipeSearch))||normalizeText(englishUI(r.name)).includes(normalizeText(recipeSearch))||r.ingredients.some(i=>normalizeText(INGREDIENT_EN[i.id]||'').includes(normalizeText(recipeSearch))))) };
document.addEventListener('click',event=>{const button=event.target.closest('#app-language');if(button)changeAppLanguage(appLanguage==='vi'?'en':'vi')});
// Localise newly inserted picker/search results without changing stored content.
new MutationObserver(records=>{if(records.some(r=>r.addedNodes.length))applyLanguage()}).observe(document.body,{childList:true,subtree:true});
